input.command:
awk '{
  line=$0
  # closing tags
  while (match(line, /<\/([a-zA-Z][a-zA-Z0-9]*)>/, m)) { cl[m[1]]++; line=substr(line, RSTART+RLENGTH) }
  # self-closing tags
  while (match(line, /<[a-zA-Z][a-zA-Z0-9]*[^>]*\/>/, m)) { line=substr(line, RSTART+RLENGTH) }
  # opening tags
  while (match(line, /<([a-zA-Z][a-zA-Z0-9]*)(([^>"]|"[^"]*")*)>/, m)) { op[m[1]]++; line=substr(line, RSTART+RLENGTH) }
} END {
  ok=1
  for (t in op) { if (op[t] != cl[t]) { print "MISMATCH:", t, "open=" op[t], "close=" cl[t]; ok=0 } }
  for (t in cl) { if (!(t in op)) { print "EXTRA CLOSE:", t; ok=0 } }
  if (ok) print "OK: all tags balanced"
}' /work/SystemContext.svg

